#
# This workspace does not currently define a language-specific build system, so
# these targets provide a safe, conventional starting point. Extend them as the
# project grows.

SHELL := /bin/sh

.PHONY: all help clean build test lint format

all: build

help:
	@echo "Available targets:"
	@echo "  make all     - Run the default build target"
	@echo "  make build   - Build the project (placeholder)"
	@echo "  make test    - Run tests (placeholder)"
	@echo "  make lint    - Run linters (placeholder)"
	@echo "  make format  - Format source files (placeholder)"
	@echo "  make clean   - Remove common generated artifacts"

build:
