clean:
	@echo "Removing common generated artifacts..."
	@rm -rf \
		build \
		dist \
		coverage \
		.pytest_cache \
		.mypy_cache \
		.ruff_cache \
		.cache \
		node_modules/.cache
	@find . -type f \( -name '*.o' -o -name '*.pyc' -o -name '*~' \) -delete
	@find . -type d -name '__pycache__' -prune -exec rm -rf {} +
